package io.knowledgebrain.learning;
import java.util.*;import java.time.Clock;import jakarta.servlet.http.Cookie;
import org.junit.jupiter.api.*;import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.web.server.ResponseStatusException;import org.springframework.http.HttpStatus;
import io.micrometer.core.instrument.simple.SimpleMeterRegistry;import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;
class PublicRoadmapApiTest {
 PublicRoadmapStore store;SpaceAuthorizationClient authority;PublicRoadmapController api;UUID space,id,actor;
 @BeforeEach void setup(){var ids=new UuidV7(Clock.systemUTC());space=ids.next();id=ids.next();actor=ids.next();store=mock(PublicRoadmapStore.class);authority=mock(SpaceAuthorizationClient.class);var metrics=new SimpleMeterRegistry();api=new PublicRoadmapController(store,authority,new RoadmapController(mock(RoadmapStore.class),authority,metrics,"https://localhost:8443"),metrics,"https://localhost:8443");when(authority.authorize(eq(space),any(),anyString(),eq("PUBLIC"),anyString())).thenReturn(actor);}
 MockHttpServletRequest r(String method,String body){var r=new MockHttpServletRequest(method,"/");r.setSecure(true);r.setCookies(new Cookie("__Host-brain_guest","a".repeat(43)));r.addHeader("Origin","https://localhost:8443");r.setContentType("application/json");r.setContent(body.getBytes(java.nio.charset.StandardCharsets.UTF_8));return r;}
 @Test void eachReadUsesFreshPublicAuthorityBeforeCanonicalAndDenialReadsNothing(){when(store.list(space,null,20)).thenReturn(new PublicRoadmapStore.Page(List.of(),null));for(int i=0;i<2;i++)assertEquals("no-store",api.list(space.toString(),r("GET","")).getHeaders().getCacheControl());var order=inOrder(authority,store);for(int i=0;i<2;i++){order.verify(authority).authorize(eq(space),eq("a".repeat(43)),eq("PUBLIC_ROADMAP_READ"),eq("PUBLIC"),anyString());order.verify(store).list(space,null,20);}reset(store);when(authority.authorize(eq(space),any(),anyString(),eq("PUBLIC"),anyString())).thenThrow(new ResponseStatusException(HttpStatus.FORBIDDEN));assertThrows(ResponseStatusException.class,()->api.get(space.toString(),id.toString(),r("GET","")));verifyNoInteractions(store);}
 @Test void publicWriteJsonDoesNotAcceptPrivateFieldsDuplicateKeysOrTrailingTokens()throws Exception{for(String body:List.of("{}","{\"title\":\"A\",\"title\":\"B\"}","{} {}","{\"roadmapId\":null,\"baseVersion\":0,\"title\":\"A\",\"description\":\"\",\"rationale\":\"R\",\"nodes\":[],\"edges\":[],\"progress\":[]}")){assertThrows(ResponseStatusException.class,()->api.submit(space.toString(),r("POST",body)));}verifyNoInteractions(store);}
 @Test void writesRequireOriginStrongContributionTagAndCurrentReviewerCapability()throws Exception{for(String tag:List.of("\"p1\"","W/\"pc1\"","\"pc0\"","\"pc9223372036854775808\"")){var r=r("POST","{}");r.addHeader("If-Match",tag);assertThrows(ResponseStatusException.class,()->api.merge(space.toString(),id.toString(),r));}assertEquals(428,assertThrows(ResponseStatusException.class,()->api.merge(space.toString(),id.toString(),r("POST","{}"))).getStatusCode().value());var foreign=r("POST","{}");foreign.removeHeader("Origin");foreign.addHeader("Origin","https://foreign.invalid");assertEquals(403,assertThrows(ResponseStatusException.class,()->api.submit(space.toString(),foreign)).getStatusCode().value());verifyNoInteractions(store);}
 @Test void malformedGetQueryBodyAndDuplicateCookiesNeverReachStore(){for(String limit:List.of("0","101","01")){var r=r("GET","");r.addParameter("limit",limit);assertThrows(ResponseStatusException.class,()->api.list(space.toString(),r));}var duplicate=r("GET","");duplicate.addParameter("limit","1","2");assertThrows(ResponseStatusException.class,()->api.proposals(space.toString(),duplicate));assertThrows(ResponseStatusException.class,()->api.get(space.toString(),id.toString(),r("GET","{}")));var cookies=r("GET","");cookies.setCookies(new Cookie("__Host-brain_guest","a".repeat(43)),new Cookie("__Host-brain_guest","b".repeat(43)));assertEquals(401,assertThrows(ResponseStatusException.class,()->api.get(space.toString(),id.toString(),cookies)).getStatusCode().value());verifyNoInteractions(store);}
}
